import { appendFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, resolve } from "node:path";

import {
  resolveActionInputs,
  type ActionInputs,
} from "./contract.ts";
import {
  GhCliApi,
  type GitHubApi,
  type ReleaseSnapshot,
} from "./github.ts";
import {
  observeExistingBody,
  prepareNotes,
  type PreparedNotes,
} from "./prepare.ts";
import { verifyRemoteTagBinding } from "./git.ts";
import { readReleaseConfig } from "./release-config.ts";
import { resolveSeriesLatest } from "./release-execution.ts";
import { prerelease } from "semver";

interface SpawnResult {
  status: number | null;
  error?: Error;
  stdout?: string;
  stderr?: string;
}

type SpawnPublisher = (
  command: string,
  args: readonly string[],
  options: {
    cwd: string;
    env: NodeJS.ProcessEnv;
    stdio: "inherit";
  },
) => SpawnResult;

type AppendOutput = (
  path: string,
  data: string,
  options: { encoding: "utf8" },
) => void;

function nodeMajor(version: string): number {
  const major = Number.parseInt(version.split(".", 1)[0] ?? "", 10);
  if (!Number.isInteger(major)) {
    throw new Error(`could not parse Node.js version: ${version}`);
  }
  return major;
}

export function requireNode24(version = process.versions.node): void {
  if (nodeMajor(version) < 24) {
    throw new Error(
      `releaseway/actions requires Node.js 24 or newer; found ${version}`,
    );
  }
}

function requiredEnvironment(
  env: NodeJS.ProcessEnv,
  name: string,
): string {
  const value = env[name];
  if (!value) {
    throw new Error(`${name} is required`);
  }
  return value;
}

export function resolveActionPath(
  explicit: string | undefined,
  env: NodeJS.ProcessEnv,
  argv: readonly string[] = process.argv,
): string {
  if (explicit) return resolve(explicit);
  if (env.GITHUB_ACTION_PATH) return resolve(env.GITHUB_ACTION_PATH);

  const entrypoint = argv[1];
  if (!entrypoint) {
    throw new Error("unable to determine action installation path");
  }
  return resolve(dirname(entrypoint), "..");
}

function writeOutputs(
  outputPath: string,
  entries: Record<string, string>,
  appendOutput: AppendOutput,
): void {
  const data = Object.entries(entries)
    .map(([key, value]) => `${key}=${value}\n`)
    .join("");
  appendOutput(outputPath, data, { encoding: "utf8" });
}

function shouldPreserve(
  existing: ReleaseSnapshot,
  inputs: ActionInputs,
): boolean {
  return (
    inputs.notesExisting === "preserve" ||
    (inputs.notesExisting === "auto" && !existing.draft)
  );
}

function verifyPublishedTitle(
  existing: ReleaseSnapshot,
  env: NodeJS.ProcessEnv,
): void {
  const requested = env.INPUT_TITLE ?? "";
  if (requested !== "" && requested !== existing.name) {
    throw new Error(
      `existing published release title does not match requested title: expected=${requested} actual=${existing.name}`,
    );
  }
}

function defaultIdentityCheck(
  workspace: string,
  repository: string,
): void {
  const origin = spawnSync(
    "git",
    ["-C", workspace, "remote", "get-url", "origin"],
    { encoding: "utf8", timeout: 30_000 },
  );
  if (origin.status !== 0) {
    throw new Error("could not resolve checkout origin");
  }
  const remote = (origin.stdout ?? "").trim();
  const resolved = spawnSync(
    "gh",
    ["repo", "view", remote, "--json", "nameWithOwner", "--jq", ".nameWithOwner"],
    { encoding: "utf8", env: process.env, timeout: 30_000 },
  );
  if (resolved.status !== 0) {
    throw new Error("could not resolve checkout repository identity");
  }
  const actual = (resolved.stdout ?? "").trim();
  if (actual !== repository) {
    throw new Error(
      `checkout repository does not match GITHUB_REPOSITORY: checkout=${actual} expected=${repository}`,
    );
  }
}

function defaultProvenanceCheck(options: {
  workspace: string;
  repository: string;
  tag: string;
  commit: string;
}): void {
  defaultIdentityCheck(options.workspace, options.repository);
  verifyRemoteTagBinding({
    workspace: options.workspace,
    tag: options.tag,
    expectedCommit: options.commit,
  });
}

export async function runAction(
  options: {
    env?: NodeJS.ProcessEnv;
    actionPath?: string;
    argv?: readonly string[];
    spawnPublisher?: SpawnPublisher;
    appendOutput?: AppendOutput;
    nodeVersion?: string;
    api?: GitHubApi;
    provenanceCheck?: (options: {
      workspace: string;
      repository: string;
      tag: string;
      commit: string;
    }) => void;
  } = {},
): Promise<void> {
  const env = options.env ?? process.env;
  requireNode24(options.nodeVersion ?? process.versions.node);
  const inputs = resolveActionInputs(env);
  const repository = requiredEnvironment(env, "GITHUB_REPOSITORY");
  const outputPath = requiredEnvironment(env, "GITHUB_OUTPUT");
  const tag = requiredEnvironment(env, "INPUT_TAG");
  const commit = requiredEnvironment(env, "INPUT_COMMIT").toLowerCase();
  const workspace = env.GITHUB_WORKSPACE || process.cwd();
  const runnerTemp = env.RUNNER_TEMP;
  const actionPath = resolveActionPath(
    options.actionPath,
    env,
    options.argv ?? process.argv,
  );
  const api = options.api ?? new GhCliApi();
  const appendOutput = options.appendOutput ?? appendFileSync;
  (options.provenanceCheck ?? defaultProvenanceCheck)({
    workspace,
    repository,
    tag,
    commit,
  });
  if (inputs.latest === "current-series") {
    const releaseConfig = readReleaseConfig(workspace, env.INPUT_RELEASE_CONFIG || ".github/releaseway.yml");
    resolveSeriesLatest(workspace, releaseConfig, tag, commit);
    if ((prerelease(tag.slice(releaseConfig.tagPrefix.length)) !== null) !== inputs.prerelease) throw new Error("Current-series tag prerelease state does not match the requested release");
  }
  const existing = await api.releaseByTag(repository, tag);

  if (existing && existing.prerelease !== inputs.prerelease) {
    throw new Error(
      `existing release prerelease state does not match requested state: ${tag}`,
    );
  }
  if (existing && !existing.draft) {
    verifyPublishedTitle(existing, env);
  }

  let prepared: PreparedNotes;
  let notesState: "prepared" | "verified" | "preserved";
  let preserveBody = false;

  if (inputs.notesPreview) {
    prepared = await prepareNotes({
      inputs,
      repository,
      tag,
      commit,
      workspace,
      runnerTemp,
      api,
    });
    writeOutputs(
      outputPath,
      {
        state: "preview",
        "release-url": "",
        "notes-path": prepared.notesPath,
        "notes-report": prepared.reportPath,
        "notes-state": "prepared",
      },
      appendOutput,
    );
    return;
  }

  if (existing && shouldPreserve(existing, inputs)) {
    prepared = await observeExistingBody({
      mode: inputs.notes,
      body: existing.body,
      runnerTemp,
      releaseId: existing.id,
      draft: existing.draft,
    });
    notesState = "preserved";
    preserveBody = true;
  } else {
    prepared = await prepareNotes({
      inputs,
      repository,
      tag,
      commit,
      workspace,
      runnerTemp,
      api,
    });
    if (existing && existing.body !== prepared.body) {
      throw new Error(
        `existing release notes do not match requested notes for ${tag}`,
      );
    }
    notesState = "verified";
  }

  const childEnv: NodeJS.ProcessEnv = {
    ...env,
    INPUT_NOTES: inputs.notes,
    INPUT_NOTES_CONFIG: inputs.notesConfig,
    INPUT_NOTES_FILE: preserveBody ? "" : prepared.notesPath,
    INPUT_NOTES_EXISTING: inputs.notesExisting,
    INPUT_NOTES_PREVIEW: "false",
    INPUT_PRERELEASE: String(inputs.prerelease),
    INPUT_LATEST: inputs.latest,
    RELEASE_ACTIONS_PRESERVE_BODY: preserveBody ? "true" : "false",
    RELEASE_ACTIONS_ACCEPTED_BODY_FILE: preserveBody
      ? prepared.notesPath
      : "",
    RELEASE_ACTIONS_VERIFY_TITLE:
      existing &&
      !existing.draft &&
      (env.INPUT_TITLE ?? "") === ""
        ? "false"
        : "true",
    RELEASE_ACTIONS_NODE: process.execPath,
    RELEASE_ACTIONS_ENGINE: resolve(actionPath, "dist/engine.cjs"),
  };

  const spawnPublisher =
    options.spawnPublisher ??
    ((command, args, spawnOptions) =>
      spawnSync(command, [...args], spawnOptions));

  const result = spawnPublisher(
    "bash",
    [resolve(actionPath, "scripts/release.sh")],
    {
      cwd: workspace,
      env: childEnv,
      stdio: "inherit",
    },
  );

  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(
      `release publisher exited with status ${result.status ?? "unknown"}`,
    );
  }

  writeOutputs(
    outputPath,
    {
      "notes-path": prepared.notesPath,
      "notes-report": prepared.reportPath,
      "notes-state": notesState,
    },
    appendOutput,
  );
}

import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { valid, prerelease, compare } from "semver";
import { GitRepository } from "./git.ts";
import type { ReleaseConfig } from "./release-config.ts";
import { nextSeriesVersion, seriesTags, type SeriesTag } from "./series.ts";
import { parseVersionedTag } from "./range.ts";

export interface ReleasePlan {
  schema: 1;
  config: ReleaseConfig;
  source: string;
  commit: string;
  tag: string;
  version: string;
  prereleaseId: string;
  latest: "automatic" | "true" | "false";
  state: "planned" | "existing";
}

const digest = (config: ReleaseConfig) => createHash("sha256").update(JSON.stringify(config)).digest("hex");

function validateRefs(git: GitRepository, config: ReleaseConfig): void {
  git.run(["check-ref-format", `refs/heads/${config.branch}`]);
  git.run(["check-ref-format", `refs/tags/${config.tagPrefix}0.0.0`]);
  if (config.series) git.run(["check-ref-format", `refs/tags/${config.series.baseTag}`]);
}

function snapshot(git: GitRepository, config: ReleaseConfig): { branch: string; tags: SeriesTag[] } {
  validateRefs(git, config);
  const refs = git.run(["ls-remote", "origin", `refs/heads/${config.branch}`, "refs/tags/*"]).stdout;
  const entries = new Map<string, { direct?: string; peeled?: string }>();
  let branch = "";
  for (const line of refs.trim().split("\n")) {
    const [sha, ref] = line.split(/\s+/);
    if (!sha || !ref || !/^[0-9a-f]{40}$/.test(sha)) continue;
    if (ref === `refs/heads/${config.branch}`) branch = sha;
    else if (ref.startsWith("refs/tags/")) {
      const peeled = ref.endsWith("^{}");
      const name = ref.slice(10, peeled ? -3 : undefined);
      const tag = entries.get(name) ?? {};
      if (peeled) tag.peeled = sha;
      else tag.direct = sha;
      entries.set(name, tag);
    }
  }
  if (!branch) throw new Error(`Origin branch does not exist: ${config.branch}`);
  // Private evidence refs never overwrite user tags or branches.
  git.run(["fetch", "--no-tags", "origin", `+refs/heads/${config.branch}:refs/releaseway/branch`, "+refs/tags/*:refs/releaseway/tags/*"]);
  if (git.resolveCommit("refs/releaseway/branch") !== branch) throw new Error("Origin branch changed while reading release state; retry planning");
  const tags: SeriesTag[] = [];
  for (const [tag, entry] of entries) {
    const commit = entry.peeled ?? entry.direct!;
    if (git.resolveCommit(`refs/releaseway/tags/${tag}`) !== commit) throw new Error(`Origin tag changed while reading release state: ${tag}`);
    tags.push({ tag, commit });
  }
  return { branch, tags };
}

function releaseCommit(git: GitRepository, source: string, tag: string, config: ReleaseConfig): string {
  const tree = git.run(["rev-parse", `${source}^{tree}`]).stdout.trim();
  const timestamp = Number(git.run(["show", "-s", "--format=%ct", source]).stdout.trim()) + 1;
  const result = spawnSync("git", ["-C", git.path, "commit-tree", tree, "-p", source], {
    input: `chore(release): ${tag}\n\nReleaseway-Config: ${digest(config)}\n`,
    encoding: "utf8",
    timeout: 30_000,
    env: {
      ...process.env,
      GIT_AUTHOR_NAME: "github-actions[bot]", GIT_AUTHOR_EMAIL: "41898282+github-actions[bot]@users.noreply.github.com",
      GIT_COMMITTER_NAME: "github-actions[bot]", GIT_COMMITTER_EMAIL: "41898282+github-actions[bot]@users.noreply.github.com",
      GIT_AUTHOR_DATE: `${timestamp} +0000`, GIT_COMMITTER_DATE: `${timestamp} +0000`,
    },
  });
  if (result.error || result.status !== 0) throw new Error(`Could not create release commit: ${result.error?.message ?? result.stderr}`);
  return result.stdout.trim();
}

function latestPolicy(config: ReleaseConfig, version: string): ReleasePlan["latest"] {
  if (config.latest === "current-series") return prerelease(version) === null ? "true" : "false";
  if (config.latest === "true" && prerelease(version) !== null) throw new Error("Prerelease cannot be marked latest");
  return config.latest;
}

export function planRelease(workspace: string, config: ReleaseConfig, prereleaseId = "", explicitSource?: string): ReleasePlan {
  const git = new GitRepository(workspace);
  if (git.run(["status", "--porcelain", "--untracked-files=no"]).stdout.trim()) throw new Error("Release planning requires clean tracked source files");
  const remote = snapshot(git, config);
  const head = explicitSource ?? git.resolveCommit("HEAD");
  if (!/^[0-9a-f]{40}$/.test(head)) throw new Error("Release source must be a full commit SHA");
  const message = git.run(["show", "-s", "--format=%B", head]).stdout.trim();
  const marker = message.match(/^chore\(release\): (\S+)\n\nReleaseway-Config: ([0-9a-f]{64})$/);
  if (!explicitSource && marker && marker[2] === digest(config)) {
    const tag = marker[1]!;
    const source = git.resolveCommit(`${head}^`);
    if (releaseCommit(git, source, tag, config) !== head) throw new Error("Release marker does not match deterministic release commit");
    const existing = remote.tags.find((entry) => entry.tag === tag);
    if (existing?.commit !== head || !git.isAncestor(head, remote.branch)) throw new Error("Release marker is not committed on origin with its matching tag");
    const version = tag.slice(config.tagPrefix.length);
    if (!tag.startsWith(config.tagPrefix) || valid(version) !== version) throw new Error("Release marker has an invalid version tag");
    if ((prerelease(version)?.[0] ?? "") !== prereleaseId) throw new Error("Retry prerelease-id differs from the prepared release");
    return { schema: 1, config, source, commit: head, tag, version, prereleaseId, latest: latestPolicy(config, version), state: "existing" };
  }
  const eligible = seriesTags(config, remote.tags, head, (a, b) => git.isAncestor(a, b));
  eligible.sort((a, b) => compare(a.tag.slice(config.tagPrefix.length), b.tag.slice(config.tagPrefix.length)));
  const previous = eligible.at(-1);
  const base = previous?.commit ?? (config.series ? remote.tags.find((entry) => entry.tag === config.series!.baseTag)!.commit : null);
  const messages = git.run(["log", "--format=%B%x00", ...(base ? [`${base}..${head}`] : [head])]).stdout.split("\0").filter((value) => value.trim());
  const version = nextSeriesVersion(config, eligible, messages.map((message) => message.trim()), prereleaseId);
  const tag = config.tagPrefix + version;
  git.run(["check-ref-format", `refs/tags/${tag}`]);
  const commit = releaseCommit(git, head, tag, config);
  const existing = remote.tags.find((entry) => entry.tag === tag);
  if (existing && existing.commit !== commit) throw new Error(`Release tag already exists and will not be replaced: ${tag}`);
  if (!existing && remote.branch !== head) throw new Error("Origin branch differs from the release source; refresh checkout before planning");
  if (existing && !git.isAncestor(commit, remote.branch)) throw new Error("Matching release tag is not on the configured origin branch");
  return { schema: 1, config, source: head, commit, tag, version, prereleaseId, latest: latestPolicy(config, version), state: existing ? "existing" : "planned" };
}

export function saveReleasePlan(path: string, plan: ReleasePlan): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, JSON.stringify(plan, null, 2) + "\n", { mode: 0o600 });
}

export function readReleasePlan(path: string): ReleasePlan {
  return JSON.parse(readFileSync(path, "utf8")) as ReleasePlan;
}

export function executeReleasePlan(workspace: string, plan: ReleasePlan, config: ReleaseConfig): ReleasePlan {
  if (plan.schema !== 1 || JSON.stringify(plan.config) !== JSON.stringify(config)) throw new Error("Release plan configuration changed; create a fresh plan");
  const git = new GitRepository(workspace);
  const checkout = git.resolveCommit("HEAD");
  if (checkout !== plan.source && checkout !== plan.commit) throw new Error("Saved release plan requires checkout of its source or marker commit; unrelated source cannot be used to resume");
  const fresh = planRelease(workspace, config, plan.prereleaseId, plan.source);
  for (const key of ["source", "commit", "tag", "version", "latest"] as const) {
    if (fresh[key] !== plan[key]) throw new Error(`Release plan ${key} changed; create a fresh plan`);
  }
  if (fresh.state === "existing") return fresh;
  const result = git.run(["push", "--atomic", "--no-follow-tags", `--force-with-lease=refs/heads/${config.branch}:${plan.source}`, "origin", `${plan.commit}:refs/heads/${config.branch}`, `${plan.commit}:refs/tags/${plan.tag}`], { allowFailure: true });
  // A transport failure may occur after the atomic transaction was accepted.
  const remote = snapshot(git, config);
  const bound = remote.tags.find((tag) => tag.tag === plan.tag);
  if (bound?.commit === plan.commit && git.isAncestor(plan.commit, remote.branch)) return { ...fresh, state: "existing" };
  if (result.status !== 0) throw new Error(`Atomic release push failed; no refs are rolled back or overwritten. Resume using the saved plan after checking origin. ${result.stderr?.trim() ?? ""}`);
  throw new Error("Atomic release push returned success but its remote binding could not be verified; resume using the saved plan");
}

export function resolveReleaseTag(workspace: string, tag: string, branch = "main", stableOnly = true): { tag: string; version: string; commit: string } {
  const git = new GitRepository(workspace);
  git.run(["check-ref-format", `refs/tags/${tag}`]);
  const version = tag.startsWith("v") ? tag.slice(1) : tag;
  if (valid(version) !== version || version.includes("+") || (stableOnly && prerelease(version) !== null)) throw new Error("Release tag must be exact stable SemVer vX.Y.Z");
  const remote = snapshot(git, { schema: 1, branch, tagPrefix: "v", initialVersion: "0.1.0", bump: "auto", latest: "automatic" });
  const entry = remote.tags.find((entry) => entry.tag === tag);
  if (!entry || !git.isAncestor(entry.commit, remote.branch)) throw new Error("Release tag must exist on origin and belong to the configured branch");
  return { tag, version, commit: entry.commit };
}

export function resolveSeriesLatest(workspace: string, config: ReleaseConfig, tag: string, commit: string): "true" | "false" {
  const git = new GitRepository(workspace);
  const remote = snapshot(git, config);
  const eligible = seriesTags(config, remote.tags, remote.branch, (a, b) => git.isAncestor(a, b));
  const target = eligible.find((entry) => entry.tag === tag && entry.commit === commit);
  if (!target) throw new Error("Release tag is outside the current series");
  const version = tag.slice(config.tagPrefix.length);
  if (prerelease(version) !== null) return "false";
  return eligible.some((entry) => {
    const candidate = entry.tag.slice(config.tagPrefix.length);
    return prerelease(candidate) === null && compare(candidate, version) > 0;
  }) ? "false" : "true";
}

export function bindReleaseTag(workspace: string, tag: string, commit: string, branch = "main"): { tag: string; version: string; commit: string; state: "created" | "existing" } {
  const git = new GitRepository(workspace);
  git.run(["check-ref-format", `refs/tags/${tag}`]);
  const parsed = parseVersionedTag(tag);
  if (!parsed || parsed.version.build.length) throw new Error("Tag must end in exact SemVer without build metadata");
  if (!/^[0-9a-f]{40}$/.test(commit)) throw new Error("Tag commit must be a full lowercase 40-character SHA");
  const config: ReleaseConfig = { schema: 1, branch, tagPrefix: parsed.prefix, initialVersion: "0.1.0", bump: "auto", latest: "automatic" };
  const verify = () => {
    const remote = snapshot(git, config);
    if (!git.isAncestor(commit, remote.branch)) throw new Error("Tag commit is not on the configured origin branch");
    const existing = remote.tags.find((entry) => entry.tag === tag);
    if (existing && existing.commit !== commit) throw new Error("Existing release tag resolves to a different commit and will not be replaced");
    return Boolean(existing);
  };
  if (verify()) return { tag, version: parsed.version.version, commit, state: "existing" };
  const result = git.run(["push", "--atomic", "--no-follow-tags", "origin", `${commit}:refs/tags/${tag}`], { allowFailure: true });
  if (!verify()) throw new Error(`Release tag push was not verified; retry the same binding. ${result.stderr ?? ""}`);
  return { tag, version: parsed.version.version, commit, state: "created" };
}

import { spawnSync } from "node:child_process";

export interface PullRequestAssociation {
  number: number;
  title: string;
  body: string;
  mergedAt: string | null;
  mergeCommitSha: string | null;
  userLogin: string | null;
  userType: string | null;
  labels: string[];
  baseRepository: string;
}

export interface GeneratedNativeNotes {
  body: string;
  name: string;
}

export interface ReleaseSnapshot {
  id: number;
  tag: string;
  name: string;
  body: string;
  draft: boolean;
  prerelease: boolean;
  immutable: boolean;
  url: string;
}

export interface PublishedReleaseSnapshot {
  tag: string;
  draft: boolean;
  prerelease: boolean;
}

export interface GitHubApi {
  associatedPullRequests(
    repository: string,
    commitSha: string,
  ): Promise<PullRequestAssociation[]>;
  pullRequest(
    repository: string,
    number: number,
  ): Promise<PullRequestAssociation>;
  generateReleaseNotes(options: {
    repository: string;
    tag: string;
    targetSha: string;
    previousTag?: string;
    configurationFile?: string;
  }): Promise<GeneratedNativeNotes>;
  releaseByTag(
    repository: string,
    tag: string,
  ): Promise<ReleaseSnapshot | null>;
  publishedReleases(
    repository: string,
  ): Promise<PublishedReleaseSnapshot[]>;
  releaseBody(
    repository: string,
    releaseId: number,
  ): Promise<string>;
}

type RunGh = (args: readonly string[]) => string;

function defaultRunGh(args: readonly string[]): string {
  const result = spawnSync("gh", [...args], {
    encoding: "utf8",
    env: process.env,
    timeout: 30_000,
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(
      `gh api failed: ${(result.stderr || result.stdout || "").trim()}`,
    );
  }
  return result.stdout;
}

function object(value: unknown, context: string): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error(`${context} must be an object`);
  }
  return value as Record<string, unknown>;
}

function stringOrNull(value: unknown): string | null {
  return typeof value === "string" ? value : null;
}

function associationNumber(value: unknown): number | null {
  if (
    typeof value !== "object" ||
    value === null ||
    Array.isArray(value)
  ) {
    return null;
  }
  const number = (value as Record<string, unknown>).number;
  return typeof number === "number" ? number : null;
}

function parsePullRequestView(
  value: unknown,
  repository: string,
): PullRequestAssociation | null {
  const pr = object(value, "pull request");
  if (
    typeof pr.number !== "number" ||
    typeof pr.title !== "string"
  ) {
    return null;
  }

  const mergeCommit =
    typeof pr.mergeCommit === "object" && pr.mergeCommit !== null
      ? object(pr.mergeCommit, "pull request merge commit")
      : null;
  const mergedAt =
    typeof pr.mergedAt === "string" ? pr.mergedAt : null;
  const mergeCommitSha =
    mergeCommit && typeof mergeCommit.oid === "string"
      ? mergeCommit.oid.toLowerCase()
      : null;
  if ((mergedAt === null) !== (mergeCommitSha === null)) {
    return null;
  }

  const author =
    typeof pr.author === "object" && pr.author !== null
      ? object(pr.author, "pull request author")
      : null;
  const labels = Array.isArray(pr.labels)
    ? pr.labels.flatMap((item) => {
        if (typeof item !== "object" || item === null) return [];
        const name = (item as Record<string, unknown>).name;
        return typeof name === "string" ? [name] : [];
      })
    : [];
  const rawBot = author?.is_bot ?? author?.isBot;
  const isBot =
    typeof rawBot === "boolean" ? rawBot : null;

  return {
    number: pr.number,
    title: pr.title,
    body: typeof pr.body === "string" ? pr.body : "",
    mergedAt,
    mergeCommitSha,
    userLogin: author ? stringOrNull(author.login) : null,
    userType: isBot === null ? null : isBot ? "Bot" : "User",
    labels,
    baseRepository: repository,
  };
}

export class GhCliApi implements GitHubApi {
  private readonly runGh: RunGh;

  constructor(runGh: RunGh = defaultRunGh) {
    this.runGh = runGh;
  }

  private paginatedArray(
    endpoint: (page: number) => string,
    context: string,
  ): unknown[] {
    const values: unknown[] = [];
    const pageSize = 100;
    const maxPages = 20;

    for (let page = 1; page <= maxPages; page += 1) {
      const raw = JSON.parse(
        this.runGh([
          "api",
          "-H",
          "Accept: application/vnd.github+json",
          "-H",
          "X-GitHub-Api-Version: 2026-03-10",
          endpoint(page),
        ]),
      ) as unknown;
      if (!Array.isArray(raw)) {
        throw new Error(`${context} page must be an array`);
      }
      values.push(...raw);
      if (raw.length < pageSize) return values;
    }

    throw new Error(
      `${context} exceeded bounded pagination limit of ${maxPages} pages`,
    );
  }

  async associatedPullRequests(
    repository: string,
    commitSha: string,
  ): Promise<PullRequestAssociation[]> {
    const values = this.paginatedArray(
      (page) =>
        `repos/${repository}/commits/${commitSha}/pulls?per_page=100&page=${page}`,
      "commit-to-PR response",
    );
    const numbers = [
      ...new Set(
        values.flatMap((value) => {
          const number = associationNumber(value);
          return number === null ? [] : [number];
        }),
      ),
    ];
    return Promise.all(
      numbers.map((number) => this.pullRequest(repository, number)),
    );
  }

  async pullRequest(
    repository: string,
    number: number,
  ): Promise<PullRequestAssociation> {
    const raw = JSON.parse(
      this.runGh([
        "pr",
        "view",
        String(number),
        "--repo",
        repository,
        "--json",
        "number,title,body,mergedAt,mergeCommit,author,labels",
      ]),
    ) as unknown;
    const parsed = parsePullRequestView(raw, repository);
    if (!parsed) {
      throw new Error(
        `pull request #${number} detail is missing merged landing metadata`,
      );
    }
    return parsed;
  }

  async generateReleaseNotes(options: {
    repository: string;
    tag: string;
    targetSha: string;
    previousTag?: string;
    configurationFile?: string;
  }): Promise<GeneratedNativeNotes> {
    const args = [
      "api",
      "-H",
      "Accept: application/vnd.github+json",
      "-H",
      "X-GitHub-Api-Version: 2026-03-10",
      "-X",
      "POST",
      `repos/${options.repository}/releases/generate-notes`,
      "-f",
      `tag_name=${options.tag}`,
      "-f",
      `target_commitish=${options.targetSha}`,
    ];
    if (options.previousTag) {
      args.push("-f", `previous_tag_name=${options.previousTag}`);
    }
    if (options.configurationFile) {
      args.push("-f", `configuration_file_path=${options.configurationFile}`);
    }

    const raw = object(
      JSON.parse(this.runGh(args)),
      "generated release notes response",
    );
    if (typeof raw.body !== "string" || typeof raw.name !== "string") {
      throw new Error("generated release notes response is missing name/body");
    }
    return { body: raw.body, name: raw.name };
  }

  async releaseByTag(
    repository: string,
    tag: string,
  ): Promise<ReleaseSnapshot | null> {
    let releaseIdText: string;
    try {
      releaseIdText = this.runGh([
        "release",
        "view",
        tag,
        "--repo",
        repository,
        "--json",
        "databaseId",
        "--jq",
        ".databaseId",
      ]).trim();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (/gh api failed: release not found$/i.test(message)) return null;
      throw error;
    }
    if (!/^[1-9][0-9]*$/.test(releaseIdText)) {
      throw new Error(
        `release lookup returned invalid database id for ${tag}`,
      );
    }
    const output = this.runGh([
      "api",
      "-H",
      "Accept: application/vnd.github+json",
      "-H",
      "X-GitHub-Api-Version: 2026-03-10",
      `repos/${repository}/releases/${releaseIdText}`,
    ]);
    const raw = object(JSON.parse(output), "release response");
    if (
      typeof raw.id !== "number" ||
      typeof raw.tag_name !== "string" ||
      typeof raw.draft !== "boolean" ||
      typeof raw.prerelease !== "boolean"
    ) {
      throw new Error("release response is missing required fields");
    }
    return {
      id: raw.id,
      tag: raw.tag_name,
      name: typeof raw.name === "string" ? raw.name : "",
      body: typeof raw.body === "string" ? raw.body : "",
      draft: raw.draft,
      prerelease: raw.prerelease,
      immutable: raw.immutable === true,
      url: typeof raw.html_url === "string" ? raw.html_url : "",
    };
  }

  async publishedReleases(
    repository: string,
  ): Promise<PublishedReleaseSnapshot[]> {
    const values = this.paginatedArray(
      (page) =>
        `repos/${repository}/releases?per_page=100&page=${page}`,
      "release-list response",
    );
    return values.map((item) => {
      const release = object(item, "release-list item");
      if (
        typeof release.tag_name !== "string" ||
        typeof release.draft !== "boolean" ||
        typeof release.prerelease !== "boolean"
      ) {
        throw new Error("release-list item is missing required fields");
      }
      return {
        tag: release.tag_name,
        draft: release.draft,
        prerelease: release.prerelease,
      };
    });
  }

  async releaseBody(
    repository: string,
    releaseId: number,
  ): Promise<string> {
    const raw = object(
      JSON.parse(
        this.runGh([
          "api",
          "-H",
          "Accept: application/vnd.github+json",
          "-H",
          "X-GitHub-Api-Version: 2026-03-10",
          `repos/${repository}/releases/${releaseId}`,
        ]),
      ),
      "release response",
    );
    return typeof raw.body === "string" ? raw.body : "";
  }
}

import process from "node:process";

import { publicContract } from "./contract.ts";
import { errorMessage } from "./errors.ts";
import { verifyReleaseBody } from "./prepare.ts";
import { appendFileSync } from "node:fs";
import { join } from "node:path";
import { readReleaseConfig } from "./release-config.ts";
import { planRelease, saveReleasePlan, readReleasePlan, executeReleasePlan, resolveReleaseTag, resolveSeriesLatest, bindReleaseTag } from "./release-execution.ts";

async function main(argv: readonly string[]): Promise<void> {
  const command = argv[0];
  if (command === "release-prepare") {
    const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
    const mode = process.env.INPUT_MODE || "prepare";
    const output = (values: Record<string, string>) => {
      const body = Object.entries(values).map(([key, value]) => `${key}=${value}\n`).join("");
      if (process.env.GITHUB_OUTPUT) appendFileSync(process.env.GITHUB_OUTPUT, body);
      else process.stdout.write(body);
    };
    if (mode === "resolve") {
      const release = resolveReleaseTag(workspace, process.env.INPUT_TAG || "", process.env.INPUT_BRANCH || "main");
      output({ ...release, target: release.commit, state: "existing" });
      return;
    }
    if (mode === "tag") {
      const release = bindReleaseTag(workspace, process.env.INPUT_TAG || "", process.env.INPUT_COMMIT || "", process.env.INPUT_BRANCH || "main");
      output(release);
      return;
    }
    if (!["plan", "prepare", "resume"].includes(mode)) throw new Error("mode must be plan, prepare, resume, resolve, or tag");
    const config = readReleaseConfig(workspace, process.env.INPUT_RELEASE_CONFIG || ".github/releaseway.yml");
    const path = process.env.INPUT_PLAN_PATH || join(process.env.RUNNER_TEMP || "/tmp", `releaseway-${process.env.GITHUB_RUN_ID || process.pid}-plan.json`);
    let plan = mode === "resume" ? readReleasePlan(path) : planRelease(workspace, config, process.env.INPUT_PRERELEASE_ID || "");
    saveReleasePlan(path, plan);
    output({ tag: plan.tag, version: plan.version, commit: plan.commit, source: plan.source, "plan-path": path, latest: config.latest, prerelease: String(Boolean(plan.prereleaseId)), state: plan.state });
    if (mode !== "plan") {
      plan = executeReleasePlan(workspace, plan, config);
      saveReleasePlan(path, plan);
      output({ state: plan.state });
    }
    return;
  }
  if (command === "resolve-series-latest") {
    const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
    const config = readReleaseConfig(workspace, process.env.INPUT_RELEASE_CONFIG || ".github/releaseway.yml");
    process.stdout.write(resolveSeriesLatest(workspace, config, process.env.INPUT_TAG || "", process.env.INPUT_COMMIT || "") + "\n");
    return;
  }
  if (command === "contract") {
    process.stdout.write(JSON.stringify(publicContract()) + "\n");
    return;
  }

  if (command === "verify-release-body") {
    const repository = argv[1];
    const releaseId = Number(argv[2]);
    const expectedPath = argv[3];
    if (
      !repository ||
      !Number.isInteger(releaseId) ||
      releaseId <= 0 ||
      !expectedPath
    ) {
      throw new Error(
        "verify-release-body requires repository, release id, and expected file",
      );
    }
    await verifyReleaseBody({
      repository,
      releaseId,
      expectedPath,
    });
    return;
  }

  throw new Error(
    command
      ? `unknown notes-engine command: ${command}`
      : "notes-engine command is required",
  );
}

void main(process.argv.slice(2)).catch((error) => {
  console.error(errorMessage(error));
  process.exitCode = 1;
});
